using System.Security.Cryptography;
using System.Text.Json;
using Ohno.CorpusAudit;
class Program {
 const string U="Legacy spinner stack profile lacks a zero-displacement certificate.",W="Legacy spinner zero-displacement certificate exceeds pair work limit.";
 static List<object> checks=new();static void C(bool pass,string name){checks.Add(new{name,pass});if(!pass)Console.WriteLine("FAIL "+name);}
 static AuditRow Row(AuditReport r,string name)=>r.Charts.Single(x=>x.EntryKey==Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(name+".osu"))));
 static string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p)));
 static void Main(string[] args){string h=Path.GetFullPath(args[0]),output=Path.GetFullPath(args[1]);Directory.CreateDirectory(output);var manifest=JsonDocument.Parse(File.ReadAllText(Path.Combine(h,"manifest.json"))).RootElement.GetProperty("cases");
 string temp=Path.Combine(Path.GetTempPath(),"independent-routez-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);
 try{
 foreach(var c in manifest.EnumerateArray()){string source=Path.Combine(h,c.GetProperty("path").GetString()!);C(Hash(source).Equals(c.GetProperty("sha256").GetString(),StringComparison.OrdinalIgnoreCase),c.GetProperty("name")+" pinned fixture hash");File.Copy(source,Path.Combine(temp,Path.GetFileName(source)));}
 var before=Directory.GetFiles(temp).ToDictionary(p=>Path.GetFileName(p)!,p=>(hash:Hash(p),stamp:File.GetLastWriteTimeUtc(p)));var r=AuditRunner.Run(temp);C(r.SourceCommit=="f6d0411abc865134a1dafb7fb7ef1473b621a84f"&&r.SourceState=="clean","exact clean linked source");var pin=JsonDocument.Parse(File.ReadAllText(Path.Combine(h,"expected-sources.json"))).RootElement;foreach(var p in pin.GetProperty("hashes").EnumerateObject())C(r.SourceHashes.GetValueOrDefault(p.Name)==p.Value.GetString(),"compiled source "+p.Name);
 foreach(var c in manifest.EnumerateArray()){string name=c.GetProperty("name").GetString()!;var row=Row(r,name);C(row.Read.Status=="success"&&row.Index.Status=="success",name+" read/index stages independent");C(row.Canonical.Status==c.GetProperty("canonicalStatus").GetString()&&row.Canonical.Code==c.GetProperty("canonicalCode").GetString()&&row.Canonical.ExceptionType==c.GetProperty("exceptionType").GetString(),name+" exact actual canonical outcome/type");if(c.GetProperty("canonicalStatus").GetString()=="success"&&name!="pairs1414")C(row.Consumers.Count==4&&row.Consumers.Values.All(x=>x.Status=="success"),name+" all consumer stages");else if(row.Canonical.Status!="success")C(row.Consumers.Count==0,name+" failed canonical does not fabricate consumers");}
 C(r.Complete&&r.Charts.Count==10&&r.StageOutcomes.Values.All(x=>x.Values.Sum()==10),"complete denominators");C(AuditRunner.Json(r)==AuditRunner.Json(AuditRunner.Run(temp)),"byte-identical repeat default report");C(before.All(x=>Hash(Path.Combine(temp,x.Key!))==x.Value.hash&&File.GetLastWriteTimeUtc(Path.Combine(temp,x.Key!))==x.Value.stamp),"normal scan exact bytes and timestamps unchanged");string json=AuditRunner.Json(r);C(!json.Contains(temp)&&!json.Contains("PRIVATE_")&&!json.Contains(U)&&!json.Contains(W)&&!json.Contains(".osu"),"default path/metadata/raw-exception privacy");
 foreach(string message in new[]{U,W}){
  string specific=message==U?"stack-certificate-unproven":"stack-certificate-work-limit";var exact=AuditRunner.Failure(new InvalidDataException(message));C(exact==new Outcome("unsupported-admission",specific,"InvalidDataException"),"exact message and InvalidDataException "+specific);
  foreach(string near in new[]{"prefix "+message,message+" suffix",message.ToLowerInvariant(),message.ToUpperInvariant()," "+message,message+" ",message+"\n",message.Replace("certificate","certificat")}){var o=AuditRunner.Failure(new InvalidDataException(near));C(o.Status==(message==U?"unclassified-rejection":"unsupported-admission")&&o.Code==(message==U?"production-rejection-unclassified":"production-profile")&&o.ExceptionType=="InvalidDataException","nonexact retains historical fallback: "+specific+" / "+checks.Count);}
  foreach(Exception e in new Exception[]{new FormatException(message),new OverflowException(message),new IOException(message),new InvalidOperationException(message),new FileNotFoundException(message)}){var o=AuditRunner.Failure(e);var expected=e switch {FormatException or OverflowException=>new Outcome("malformed-input","numeric-or-format",e.GetType().Name),FileNotFoundException=>new("missing-resource","file-missing",e.GetType().Name),IOException=>new("read-error","io-error",e.GetType().Name),_=>new("unexpected-failure","unexpected-exception",e.GetType().Name)};C(o==expected,"wrong type cannot select exact code: "+e.GetType().Name+" / "+specific);}
  // Real changed production fingerprints outrank an injected exact certificate failure.
  string path=Path.Combine(temp,"isolated.osu");byte[] original=File.ReadAllBytes(path);
  var changed=AuditRunner.RunCore(temp,new(),default,new((p,_)=>{if(p==path){File.AppendAllText(p,"//changed\n");throw new InvalidDataException(message);}}));C(Row(changed,"isolated").Canonical.Status=="changed-input"&&Row(changed,"isolated").Canonical.Code=="fingerprint-changed","actual byte revision outranks "+specific);File.WriteAllBytes(path,original);
  var stamp=AuditRunner.RunCore(temp,new(),default,new((p,_)=>{if(p==path){File.SetLastWriteTimeUtc(p,File.GetLastWriteTimeUtc(p).AddSeconds(4));throw new InvalidDataException(message);}}));C(Row(stamp,"isolated").Canonical.Code=="fingerprint-changed"&&File.ReadAllBytes(path).SequenceEqual(original),"timestamp-only revision outranks "+specific);
  var missing=AuditRunner.RunCore(temp,new(),default,new((p,_)=>{if(p==path){File.Delete(p);throw new InvalidDataException(message);}}));C(Row(missing,"isolated").Canonical==new Outcome("missing-resource","file-missing","FileNotFoundException"),"missing-file observation outranks "+specific);File.WriteAllBytes(path,original);
 }
 var unexpected=AuditRunner.RunCore(temp,new(),default,new((p,_)=>{if(p.EndsWith("isolated.osu",StringComparison.Ordinal))throw new InvalidOperationException(U);}));C(Row(unexpected,"isolated").Canonical==new Outcome("unexpected-failure","unexpected-exception","InvalidOperationException")&&Row(unexpected,"modern").Canonical.Status=="success","wrong-type path and individual failure isolation");
 var oldMessage=AuditRunner.Failure(new InvalidDataException("Chart changed since indexing; refresh and commit its new row: PRIVATE_PATH"));C(oldMessage.Code=="production-rejection-unclassified","text alone never establishes mutation");
 C(AuditRunner.Run(temp,new(IncludeRelativePaths:true)).Charts.All(x=>x.RelativePath is not null&&!Path.IsPathRooted(x.RelativePath)),"private paths remain explicit relative-only output");
 int failed=checks.Count(c=>!JsonSerializer.SerializeToElement(c).GetProperty("pass").GetBoolean());File.WriteAllText(Path.Combine(output,"results.json"),JsonSerializer.Serialize(new{actor="Work1 independent exact-message and actual-production QA",source=r.SourceCommit,state=r.SourceState,sourceHashes=r.SourceHashes,runtime=Environment.Version.ToString(),passed=checks.Count-failed,failed,checks,observations=r.Charts.Select(x=>new{x.EntryKey,x.Index,x.Canonical}),originalRuntime="NOT RUN",ownerCorpus="NOT RUN"},new JsonSerializerOptions{WriteIndented=true}));File.WriteAllText(Path.Combine(output,"audit.json"),AuditRunner.Json(r));Console.WriteLine($"Independent Issue11: {checks.Count-failed}/{checks.Count} PASS; {failed} FAIL");Environment.ExitCode=failed==0?0:1;
 }finally{Directory.Delete(temp,true);}
 }
}
